package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.search.api.*;import io.micrometer.core.instrument.*;import java.util.List;public final class MeasuredRetrievalGateway implements RetrievalGateway{private final RetrievalGateway delegate;private final Timer duration;private final DistributionSummary hits;public MeasuredRetrievalGateway(RetrievalGateway d,MeterRegistry m){delegate=d;duration=Timer.builder("ygh.ai.retrieval.duration").register(m);hits=DistributionSummary.builder("ygh.ai.retrieval.hits").register(m);}public List<SearchHit>search(String query,String category,int limit){return duration.record(()->{List<SearchHit>result=delegate.search(query,category,limit);hits.record(result.size());return result;});}}
